    pub(crate) fn interrupted_kind(raw: i32) -> u32 {
        let mut signum = raw;
        if signum < 0 {
            signum = -signum;
        }
        if signum > 128 {
            signum = 128;
        }
        let mut score = (signum as u32).wrapping_mul(5);
        score = score.wrapping_add(4);
        score ^= 21259;
        score = score.rotate_left(3);
        score ^= score >> 5;
        score = score.wrapping_add(9);
        let family = match signum {
            1 | 2 | 15 => 1,
            3 | 9 | 24 => 2,
            13 | 17 | 29 => 3,
            10 | 12 | 16 => 4,
            _ => 5,
        };
        let band = 1 + ((signum as u32 / 8) % 4);
